"""Model-based short vertical launch; no flight replay or object-state injection."""
import numpy as np

from .catch_online_control import RobotModel,InterceptPlan


def make_vertical_toss(offset,settings):
    model=RobotModel()
    model.capture_offset=np.asarray(offset)
    try:
        x=float(settings.get("x_m",.55))
        y=float(settings.get("y_m",0.0))
        z=float(settings.get("start_z_m",1.12))
        # The original primitive was vertical-only.  Keep that interface, but
        # allow a bounded horizontal endpoint so a long-distance toss is still
        # generated by arm motion and IK rather than by injecting object state.
        goal_x=float(settings.get("goal_x_m",x+settings.get("delta_x_m",0.0)))
        goal_y=float(settings.get("goal_y_m",y+settings.get("delta_y_m",0.0)))
        rise=float(settings.get("travel_m",.23))
        goal_z=float(settings.get("goal_z_m",z+rise))
        seed=np.array([0.,.5,-1.,np.pi,2.5,0.])
        start,point,_,rotation=model.fit_position([x,y,z],seed,tilt_weight=.3,iterations=300,capture_axis=[0,0,1])
        if np.linalg.norm(point-[x,y,z])>.003 or rotation[2,2]<.995:
            raise RuntimeError("vertical toss start pose does not fit")
        goal,point,jac,rotation=model.fit_position([goal_x,goal_y,goal_z],start,tilt_weight=.3,iterations=300,capture_axis=[0,0,1])
        if np.linalg.norm(point-[goal_x,goal_y,goal_z])>.003 or rotation[2,2]<.995:
            raise RuntimeError("vertical toss goal pose does not fit")
        _,_,angular,_=model.state(goal)
        speed,relative=model.fit_velocity(jac,[float(settings.get("speed_x_m_s",0.0)),
                                               float(settings.get("speed_y_m_s",0.0)),
                                               float(settings.get("speed_m_s",1.8))],goal,
                                         angular=angular,angular_weight=.3)
        duration=float(settings.get("duration_s",.28))
        plan=InterceptPlan(0.,duration,0.,[],[],start,np.zeros(6),goal,speed,relative,0.,0.)
        peak=max(float(np.max(np.abs(plan.evaluate(t)[1])/model.vmax)) for t in np.linspace(0,duration,101))
        if peak>1.02:
            raise RuntimeError(f"vertical toss exceeds planned joint speed: {peak:.3f}")
        return start,goal,speed,duration,dict(settings=settings,start_q=start.tolist(),goal_q=goal.tolist(),
            terminal_qd=speed.tolist(),planned_peak_speed_ratio=peak,terminal_velocity_residual_m_s=relative)
    finally:
        model.close()
